// Some portions generated by Claude
import type { ReactNode } from "react";
import { Icon } from "./icons.tsx";

export type QueryDrawerProps = {
  open: boolean;
  queryPageHref: string;
  busy: boolean;
  query: string;
  filterCount: number;
  generatedQuery: string;
  onClose: () => void;
  onQuery: (query: string) => void;
  onRun: () => void;
  onReset: () => void;
  onUseGeneratedQuery: () => void;
  /** Language and label preferences. */
  children?: ReactNode;
};

/** The query drawer: find an entity, edit and run the graph query, the visual query of the filters, preferences. */
export function QueryDrawer({
  open,
  queryPageHref,
  busy,
  query,
  filterCount,
  generatedQuery,
  onClose,
  onQuery,
  onRun,
  onReset,
  onUseGeneratedQuery,
  children,
}: QueryDrawerProps) {
  return (
    <aside
      id="query-workspace"
      className={`query-panel${open ? " is-open" : ""}`}
      aria-label="Query workspace"
    >
      <div className="panel-heading">
        <h2>Query workspace</h2>
        <button
          className="workbench-action workbench-action--ghost workbench-action--icon"
          type="button"
          aria-label="Close query workspace"
          title="Close query workspace"
          onClick={onClose}
        >
          <Icon name="close" />
        </button>
      </div>

      <p className="endpoint-caption">
        <a href={queryPageHref}>Open in Query page</a>
      </p>

      <div className="query-field">
        <div className="query-head">
          <label htmlFor="sparql">SPARQL</label>
          <span><code>CONSTRUCT</code>, <code>DESCRIBE</code> or <code>SELECT ?source ?predicate ?target</code></span>
        </div>
        <textarea id="sparql" value={query} onChange={(event) => onQuery(event.target.value)} spellCheck={false} />
      </div>

      <div className="query-actions">
        <button className="workbench-action workbench-action--primary" type="button" disabled={busy} onClick={onRun}>
          <Icon name="execute" />
          {busy ? "Querying…" : "Run query"}
        </button>
        <button className="workbench-action workbench-action--ghost" type="button" onClick={onReset}>
          Reset query
        </button>
      </div>

      <details className="visual-query">
        <summary>
          <span>Visual query</span>
          <small>
            {filterCount
              ? `${filterCount} ${filterCount === 1 ? "filter" : "filters"} applied`
              : "No active facets"}
          </small>
          <Icon name="chevron" className="workbench-disclosure-chevron" />
        </summary>
        <pre>{generatedQuery}</pre>
        <button
          className="workbench-action workbench-action--secondary"
          type="button"
          onClick={onUseGeneratedQuery}
        >
          Open in editor
        </button>
      </details>

      {children}
    </aside>
  );
}
